var o=[{title:`O que faz cada região`,text:`A coluna torácica é a secção do meio das costas e permite-lhe rodar e estender. O complexo do ombro inclui a articulação esférica e a omoplata a deslizar sobre a caixa torácica. Alcançar acima da cabeça depende de várias regiões a trabalharem em conjunto, por isso testa mais do que a flexibilidade da articulação do ombro.`},{title:`Explore o movimento confortável`,text:`Um exercício de rotação em livro aberto roda com suavidade a parte superior do corpo enquanto as ancas ficam bastante paradas. Os círculos controlados com os braços ensaiam o movimento do ombro, e o gato-camelo move a coluna em flexão e extensão a um ritmo fácil. Mova-se devagar, respire normalmente e não force a posição final.`},{title:`Mobilidade nos seus levantamentos`,text:`O press acima da cabeça pode parecer mais fluido quando as costelas, as omoplatas e os braços se movem em conjunto. Nas remadas, deixe as omoplatas moverem-se naturalmente; não precisa de as manter presas para trás o tempo todo. Procure um controlo fluido no exercício que escolheu. Não há uma postura rígida única que todos tenham de copiar.`},{title:`Mobilidade mais força`,text:`Os press leves, os deslizamentos na parede, as remadas e as caminhadas controladas com carga desenvolvem em conjunto amplitude utilizável e coordenação. O alongamento isolado pode melhorar a flexibilidade passiva sem lhe dar controlo total sob carga. Se um exercício parecer instável ou desconfortável, altere a pega, o ângulo ou a amplitude de movimento.`},{title:`Usar o TrainUp`,text:`Se o trabalho acima da cabeça incomodar o ombro, acrescente o ombro como limitação no Perfil, com uma nota. O plano escolhe apenas exercícios que se adaptam às suas limitações. Em caso de dor no ombro nova, persistente ou que piora, consulte um médico ou fisioterapeuta em vez de confiar em exercícios gerais de mobilidade.`}];var r=[{label:`ACE 2026: mobilidade versus flexibilidade`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`ACE 2026: orientações práticas de alongamento`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`Biblioteca de exercícios da ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var i={sections:o,sources:r};export{i as default,o as sections,r as sources};